--
-- Structure for view `municipal_exam_stats`
--
DROP TABLE IF EXISTS `municipal_exam_stats`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `municipal_exam_stats`  AS SELECT `m`.`id` AS `municipality_id`, `m`.`name` AS `municipality_name`, `m`.`province` AS `province`, `e`.`id` AS `exam_id`, `e`.`title` AS `exam_title`, `e`.`status` AS `exam_status`, `e`.`created_at` AS `exam_created_at`, count(distinct `a`.`id`) AS `total_applicants_assigned`, count(distinct case when `a`.`status` = 'for exam' then `a`.`id` end) AS `applicants_for_exam`, count(distinct `ex`.`id`) AS `total_examinees_assigned`, count(distinct case when `ex`.`status` = 'for exam' then `ex`.`id` end) AS `examinees_for_exam` FROM (((`municipalities` `m` left join `exams` `e` on(`m`.`id` = `e`.`municipality_id`)) left join `applicants` `a` on(`e`.`id` = `a`.`exam_id`)) left join `examinees` `ex` on(`e`.`id` = `ex`.`exam_id`)) GROUP BY `m`.`id`, `e`.`id` ORDER BY `m`.`name` ASC, `e`.`created_at` DESC ;

